{
  "claims": [
    {
      "text": "Raw persistence is essential for auditability and reconstruction of complex ceremonies, as demonstrated by the successful reconstruction of run csi-typha-1 from raw Loki logs.",
      "evidence_refs": ["ev-t4-loki-raw-value"]
    },
    {
      "text": "Summarization introduces significant risks of drift and fabrication, as shown in real runs where summaries contained false assertions not present in the original context.",
      "evidence_refs": ["ev-t4-summary-drift-risk"]
    },
    {
      "text": "Storage costs for full outputs are negligible compared to compute costs, making raw persistence economically feasible.",
      "evidence_refs": ["ev-t4-storage-cost"]
    },
    {
      "text": "While raw persistence increases audit surface and may expose PII, summaries can mitigate this risk through redaction, but only if both forms are retained.",
      "evidence_refs": ["ev-t4-pii-surface"]
    },
    {
      "text": "Preview truncation in engine logs creates a risk of losing complete outputs if consumers discard the final RunCeremony response.",
      "evidence_refs": ["ev-t4-preview-truncation"]
    }
  ],
  "decision": "accept",
  "risks": [
    "Retaining both raw and summarized forms increases storage overhead and complexity in data management.",
    "The system must ensure consistent handling of both formats across all components to avoid data loss."
  ],
  "assumptions": [
    "The system has the capacity to store and manage both raw and summarized outputs without performance degradation.",
    "Retention policies can be effectively applied to both raw and summarized data to manage PII exposure.",
    "Consumers will consistently retrieve the complete output from the RunCeremony response to avoid losing critical information."
  ]
}

